import numpy as np

def leave_one_out_baselines(rewards: np.ndarray) -> np.ndarray:
    r = np.asarray(rewards, dtype=float)
    if r.ndim != 1 or len(r) < 2:
        raise ValueError("at least two rewards are required")
    return (np.sum(r) - r) / (len(r) - 1)

def group_mean_advantages(rewards: np.ndarray) -> np.ndarray:
    r = np.asarray(rewards, dtype=float)
    if r.ndim != 1 or len(r) == 0:
        raise ValueError("rewards must be a non-empty vector")
    return r - np.mean(r)

def group_zscore_advantages(rewards: np.ndarray, eps: float = 1e-8) -> np.ndarray:
    centered = group_mean_advantages(rewards)
    scale = float(np.sqrt(np.mean(centered ** 2)))
    if scale < eps:
        return np.zeros_like(centered)
    return centered / scale
```

This uses the within-group population variance with denominator $G$, a common convention for normalized advantages.

