import numpy as np

def response_token_mask(input_ids, prompt_lengths, pad_token_id, eos_token_id):
    ids = np.asarray(input_ids)
    lengths = np.asarray(prompt_lengths, dtype=int)
    if ids.ndim != 2 or lengths.shape != (ids.shape[0],):
        raise ValueError("input_ids must be [B, T] and prompt_lengths [B]")
    mask = np.zeros((ids.shape[0], ids.shape[1] - 1), dtype=float)
    for b in range(ids.shape[0]):
        active = True
        for pos in range(1, ids.shape[1]):
            token = int(ids[b, pos])
            if pos < lengths[b] or token == pad_token_id or not active:
                continue
            mask[b, pos - 1] = 1.0
            if token == eos_token_id:
                active = False
    return mask

def sequence_log_probability(token_log_probs, mask=None):
    lp = np.asarray(token_log_probs, dtype=float)
    if mask is None:
        return np.sum(lp, axis=-1)
    m = np.asarray(mask, dtype=float)
    if m.shape != lp.shape:
        raise ValueError("mask must match token_log_probs")
    return np.sum(lp * m, axis=-1)

def broadcast_sequence_advantages(sequence_advantages, token_mask):
    a = np.asarray(sequence_advantages, dtype=float)
    m = np.asarray(token_mask, dtype=float)
    if a.ndim != 1 or m.ndim != 2 or m.shape[0] != a.shape[0]:
        raise ValueError("advantages must be [B] and token_mask [B, T]")
    return a[:, None] * m
```

The mask is shifted relative to the original tokens because logits at position $k$ score the label at position $k+1$. A generated EOS is a policy action and is included; prompt, PAD, and the post-EOS tail are excluded. Broadcasting one advantage implements a whole-response score-function objective, but it does not become a local explanation of token credit.
